// routing.simulate: Which queues a publish reaches in a vhost, and by which path
// Generated by `pnpm nx g @app/generators:action routing.simulate`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  HEADERS_MAX,
  HeadersSchema,
  RoutingResultSchema,
} from './routing-types.ts';
import {
  SnapshotMetaSchema,
  TOPOLOGY_NAME_MAX,
  TopologyGapsSchema,
  VhostNameSchema,
} from './topology-types.ts';

const key = z.string().max(TOPOLOGY_NAME_MAX);

export const RoutingSimulateInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  vhost: VhostNameSchema,
  /** The exchange published to; the empty name is the default exchange. */
  exchange: key,
  routingKey: key,
  /** The message headers; the broker reads `CC` and `BCC` (lists of routing keys) and `x-` headers from them. */
  headers: HeadersSchema.optional(),
  /** Additional routing keys (the `CC` header). Replaces a `CC` header, if both are given. */
  cc: z.array(key).max(HEADERS_MAX).optional(),
  /** Hidden routing keys (the `BCC` header). Replaces a `BCC` header, if both are given. */
  bcc: z.array(key).max(HEADERS_MAX).optional(),
  /** A publish with the mandatory flag: an unroutable message is returned to the publisher. */
  mandatory: z.boolean().optional(),
  /** Read the broker again instead of using a snapshot taken in the last seconds. */
  refresh: z.boolean().optional(),
});

export const RoutingSimulateOutputSchema = z.strictObject({
  vhost: VhostNameSchema,
  /**
   * What the simulator says for the vhost as it was read. `exact` and `unroutable` are false
   * whenever `gaps` is not empty: an answer built on a policy that could not be read is not exact.
   */
  result: RoutingResultSchema,
  gaps: TopologyGapsSchema,
  snapshot: SnapshotMetaSchema,
});

export const routingSimulate = defineAction({
  id: 'routing.simulate',
  kind: 'query',
  summary: 'Which queues a publish reaches in a vhost, and by which path',
  input: RoutingSimulateInputSchema,
  output: RoutingSimulateOutputSchema,
  permission: 'broker.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({
    connectionId: input.cid,
    vhost: input.vhost,
    kind: 'exchange',
    name: input.exchange,
  }),
  http: { method: 'POST', path: '/connections/{cid}/routing/simulations' },
  mcp: {
    expose: true,
    mutating: false,
    title: 'Simulate a publish',
    description:
      'Which queues a message published with this exchange, routing key and headers reaches, by which bindings, and the alternate-exchange path or that it is unroutable. Nothing is published.',
  },
  cli: { command: 'routing simulate' },
  since: '1.0',
});
